package com.notireader.app.presentation.view_chat_screen_activity

import androidx.lifecycle.LiveData
import androidx.lifecycle.ViewModel
import androidx.lifecycle.asLiveData
import com.notireader.app.domain.models.MessageModel
import com.notireader.app.domain.repository.NotiRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import javax.inject.Inject

@HiltViewModel
class ViewChatViewModel @Inject constructor(
    private val notiRepository: NotiRepository
) : ViewModel() {
    fun getMessagesForSender(sender: String): LiveData<List<MessageModel>> =
        notiRepository.getMessagesForSender(sender).asLiveData()
}

package com.notireader.app.presentation.whatsapp_screen_fragment

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.recyclerview.widget.RecyclerView
import com.notireader.app.databinding.ItemSenderBinding

class SenderAdapter(
    private val senders: List<String>,
    private val onClick: (String) -> Unit
) : RecyclerView.Adapter<SenderAdapter.SenderViewHolder>() {

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): SenderViewHolder {
        val binding = ItemSenderBinding.inflate(LayoutInflater.from(parent.context), parent, false)
        return SenderViewHolder(binding)
    }

    override fun onBindViewHolder(holder: SenderViewHolder, position: Int) {
        holder.bind(senders[position])
    }

    override fun getItemCount(): Int = senders.size

    inner class SenderViewHolder(private val binding: ItemSenderBinding) : RecyclerView.ViewHolder(binding.root) {
        fun bind(sender: String) {
            binding.senderName.text = sender
            binding.root.setOnClickListener { onClick(sender) }
        }
    }
}

package com.notireader.app.presentation.whatsapp_screen_fragment

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.Fragment
import androidx.fragment.app.viewModels
import androidx.lifecycle.Observer
import com.notireader.app.R
import com.notireader.app.databinding.FragmentWhatsappBinding
import dagger.hilt.android.AndroidEntryPoint

@AndroidEntryPoint
class WhatsappFragment : Fragment() {

    companion object {
        fun newInstance() = WhatsappFragment()
    }

    private val viewModel: WhatsappViewModel by viewModels()

    private var _binding: FragmentWhatsappBinding? = null
    private val binding get() = _binding!!

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentWhatsappBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        viewModel.allMessages.observe(viewLifecycleOwner, Observer { messages ->
            if (!messages.isNullOrEmpty()) {
                val latest = messages.last()
                binding.senderName.text = latest.sender
                binding.message.text = latest.message
                binding.timeStamp.text = latest.timestamp.toString()
            } else {
                binding.senderName.text = "No messages"
                binding.message.text = ""
                binding.timeStamp.text = ""
            }
        })
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.notireader.app.presentation.whatsapp_screen_fragment

import android.content.Intent
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.Fragment
import androidx.fragment.app.viewModels
import androidx.lifecycle.Observer
import androidx.recyclerview.widget.LinearLayoutManager
import com.notireader.app.R
import com.notireader.app.databinding.FragmentWhatsappBinding
import com.notireader.app.presentation.view_chat_screen_activity.ViewChat
import dagger.hilt.android.AndroidEntryPoint

@AndroidEntryPoint
class WhatsappFragment : Fragment() {

    companion object {
        fun newInstance() = WhatsappFragment()
    }

    private val viewModel: WhatsappViewModel by viewModels()

    private var _binding: FragmentWhatsappBinding? = null
    private val binding get() = _binding!!

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentWhatsappBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        viewModel.allMessages.observe(viewLifecycleOwner, Observer { messages ->
            if (!messages.isNullOrEmpty()) {
                // Show latest message as before
                val latest = messages.last()
                binding.senderName.text = latest.sender
                binding.message.text = latest.message
                binding.timeStamp.text = latest.timestamp.toString()

                // List unique senders
                val uniqueSenders = messages.map { it.sender }.distinct()
                val adapter = SenderAdapter(uniqueSenders) { senderName ->
                    val intent = Intent(requireContext(), ViewChat::class.java)
                    intent.putExtra("sender_name", senderName)
                    startActivity(intent)
                }
                binding.senderRecyclerView.layoutManager = LinearLayoutManager(requireContext())
                binding.senderRecyclerView.adapter = adapter
            } else {
                binding.senderName.text = "No messages"
                binding.message.text = ""
                binding.timeStamp.text = ""
            }
        })
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}
